#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "Use-after-free of UArenaScoreTracker. ScoreTracker was declared as a raw C++ pointer (UArenaScoreTracker* ScoreTracker) WITHOUT UPROPERTY(), unlike Hud and Palette. The tracker created via NewObject in BeginPlay was therefore invisible to the garbage collector; once GC ran (log: 'LogGarbage: Collecting garbage: 412 objects purged') the object was reclaimed, leaving a dangling pointer. When OnGoalScored fired ~a minute into play, ScoreTracker->AddPoints() dereferenced the freed object (ArenaScoreTracker.cpp:18) -> EXCEPTION_ACCESS_VIOLATION reading address 0xffffffffffffffff.",
  "no_colors_cause": "The color palette DataAsset /Game/Data/Palettes/DA_Primary was never cooked into the packaged build. Config/DefaultGame.ini listed only /Game/Data/Effects under DirectoriesToAlwaysCook, so the Palettes folder was excluded from the .pak. At startup LoadObject<UArenaPalette> failed (log: \"Couldn't find file for package /Game/Data/Palettes/DA_Primary\" and \"Failed to find object 'ArenaPalette /Game/Data/Palettes/DA_Primary.DA_Primary'\"), Palette stayed null, and the game fell back to gray (\"Palette is null, using fallback gray\"). In the editor all assets are live, so colors showed fine.",
  "fixes_applied": [
    "Source/PixelArena/ArenaGameMode.h: changed ScoreTracker from a raw UPROPERTY-less pointer to UPROPERTY() TObjectPtr<UArenaScoreTracker>, so the GC keeps it alive for the lifetime of the GameMode (matching Hud/Palette).",
    "Config/DefaultGame.ini: added +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") so DA_Primary is baked into the packaged build."
  ],
  "evidence": {
    "crash_log_lines": "Saved/Logs/PixelArena-shipping.log lines 8-14 (GC purge at 21:05:13, fatal ACCESS_VIOLATION at 21:05:27 in UArenaScoreTracker::AddPoints <- AArenaGameMode::OnGoalScored)",
    "no_colors_log_lines": "Saved/Logs/PixelArena-shipping.log lines 4-6 (package missing, object not found, fallback gray warning)"
  }
}
